// ============================================================
// Code: Parse Copy Response
// Extracts the JSON object from Gemini's candidates response.
// Merges it with the original content row and client asset fields.
// Uses .item (not .first) so data is correctly paired per loop iteration.
// ============================================================

const rawText = $input.first().json.candidates[0].content.parts[0].text;

const cleanedText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

try {
  const parsed = JSON.parse(cleanedText);

  // .item gives the paired item for THIS loop iteration (not always the first)
  const contentRow = $('Loop Over Items').item.json;
  const client = $('DB: Get Client Details').item.json;

  return [{
    json: {
      // Content row identifiers needed downstream
      id:              contentRow.id,
      client_id:       contentRow.client_id,
      day_number:      contentRow.day_number,
      format:          contentRow.format,
      core_topic:      contentRow.core_topic,
      image_prompt:    contentRow.image_prompt,
      keywords:        contentRow.keywords,
      cta:             contentRow.cta,
      posting_date:    contentRow.posting_date,
      // Generated copy from Gemini
      post_copy:         parsed.post_copy,
      hashtags:          parsed.hashtags,
      carousel_content:  parsed.carousel_content,
      // after carousel_content: parsed.carousel_content,
      slide_1_body: parsed.carousel_content?.slide_1?.body ?? '',
      slide_2_body: parsed.carousel_content?.slide_2?.body ?? '',
      slide_3_body: parsed.carousel_content?.slide_3?.body ?? '',
      slide_4_body: parsed.carousel_content?.slide_4?.body ?? '',
      slide_5_body: parsed.carousel_content?.slide_5?.body ?? '',
      slide_6_body: parsed.carousel_content?.slide_6?.body ?? '',
      slide_7_body: parsed.carousel_content?.slide_7?.body ?? '',
      // Client asset references — use .item not .first to avoid cross-client corruption
      drive_folder_id:  client.drive_folder_id,
      drive_folder_url: 'https://drive.google.com/drive/folders/' + client.drive_folder_id,
      sheets_id:        client.sheets_id,
      logo_url: client.logo_url,
      target_platform:  contentRow.target_platform,
      strategic_angle:  contentRow.strategic_angle,
      keyword_to_use:   contentRow.keyword_to_use,
      cta_url:          contentRow.cta_url,
      arabic_required:  contentRow.arabic_required,
      hook:             parsed.hook,
      alt_text:         parsed.alt_text,
    }
  }];

} catch (error) {
  const dayNum = $('Loop Over Items').item.json.day_number;
  throw new Error(`Phase 3A — Copy parse failed for Day ${dayNum}: ${error.message}`);
}

const incoming = $input.first().json;
const copyData = $('Code: Parse Copy Response').item.json;
let imageUrl = null, slideImages = {};

if (copyData.format === 'carousel') {
  for (let i = 1; i <= 7; i++) slideImages[`slide_${i}_image_url`] = incoming[`slide_${i}_image_url`] ?? null;
  imageUrl = slideImages.slide_1_image_url;            // cover image
} else {
  const id = incoming.id ?? null;                       // Drive single-image result
  imageUrl = id ? `https://drive.google.com/file/d/${id}/view` : null;
}
return [{ json: { ...copyData, ...slideImages, image_url: imageUrl,
  all_slide_image_urls: incoming.all_slide_image_urls ?? imageUrl ?? '',
  image_model_used: 'gemini-2.5-flash-image' } }];

const data = $input.first().json;
const slides = data.carousel_content;

if (!slides || typeof slides !== 'object') {
  return [{ json: { ...data, current_slide_key: 'slide_1',
    current_slide_headline: '', current_slide_subtitle: '',
    current_slide_body: '', slide_index: 1 } }];
}

return Object.entries(slides).map(([key, slide], i) => ({
  json: {
    ...data,
    current_slide_key: key,
    current_slide_headline: typeof slide === 'object' ? slide.headline : slide,
    current_slide_subtitle: typeof slide === 'object' ? slide.subtitle : '',
    current_slide_body: typeof slide === 'object' ? slide.body : slide,
    slide_index: i + 1,
    image_prompt: `${data.image_prompt} — Slide ${i + 1}: ${typeof slide === 'object' ? slide.headline : slide}`
  }
}));

values.content:
=You are a social media designer creating a FINAL branded post image — fully composited and ready to publish. No separate text overlay will be added later. All text and layout described below must be rendered directly inside the generated image.

LAYOUT (follow exactly):
- LEFT 45% of the canvas: clean white background panel, softly blending into the photo on the right edge (no hard line).
- TOP-LEFT CORNER of the white panel: a clean rectangular placeholder zone, roughly 15% width × 8% height of the full image — a subtle light neutral or off-white rectangle with softly rounded edges, slightly separated from the background. Leave this zone EMPTY — no text, no symbols, no shapes inside it. A real brand logo will be placed here in post-processing.
- Below the placeholder (with comfortable spacing): the HEADLINE in large bold dark navy sans-serif font, left-aligned, line-broken naturally over 2–3 lines. The headline is the first 6 words of the copy below:
  "{{ $('Code: Parse Copy Response').item.json.post_copy.split(' ').slice(0,6).join(' ') }}"
- Below the headline: the BODY TEXT in smaller regular dark gray sans-serif font, left-aligned, comfortable line spacing:
  "{{ $('Code: Parse Copy Response').item.json.post_copy }}"
- RIGHT 55% of the canvas: photorealistic brand photography, soft natural light, blending gently into the white panel at the seam.

PHOTO SUBJECT (right side only):
Brief: {{ $('Code: Parse Copy Response').item.json.image_prompt }}
Topic: {{ $('Code: Parse Copy Response').item.json.core_topic }}
Brand visual style: {{ $('DB: Get Client Details').item.json.brand_guidelines.visual_style }}
Visual feel: {{ $('DB: Get Client Details').item.json.brand_guidelines.visual_feel }}
Brand color palette: {{ $('DB: Get Client Details').item.json.brand_guidelines.brand_colors }}
Products (depict accurately if relevant): {{ $('DB: Get Client Details').item.json.product_catalog }}

HARD CONSTRAINTS:
{{ $('DB: Get Client Details').item.json.brand_guidelines.visual_restrictions }}
- No watermarks, no AI-generated logos or signatures, no random text fragments anywhere on the image
- All rendered text must be clean, perfectly spelled, and fully legible — use a clear modern sans-serif typeface
- The top-left logo placeholder zone MUST remain empty
- Headline and body text MUST appear exactly as written above, with no paraphrasing or omissions
- Luxury, warm, editorial feel — soft natural light, warm neutral tones
- Aspect ratio: {{ ({Instagram:'1:1',LinkedIn:'1.91:1',Facebook:'1.91:1',Pinterest:'2:3'})[$('Code: Parse Copy Response').item.json.target_platform] || '1:1' }}

Output ONLY the final image generation prompt, no labels or commentary.

