const aggregated = $input.first().json.slides; // matches destinationFieldName above
const base = aggregated[0];

const slideImages = {};
for (const row of aggregated) {
  slideImages[`${row.current_slide_key}_image_url`] = row.image_url;
}

return [{
  json: {
    ...base,
    ...slideImages,
    all_slide_image_urls: Object.values(slideImages).filter(Boolean).join('\n')
  }
}];

const j = $input.first().json;
const id = j.id ?? null;

return [{
  json: {
    ...j,
    current_slide_key: j.current_slide_key ?? null,
    image_url: id ? `https://drive.google.com/file/d/${id}/view` : null
  }
}];
